/**
 * Proteção de acesso ao painel — Vercel Edge Middleware.
 *
 * Roda NO SERVIDOR, antes de qualquer arquivo ser entregue. Sem um cookie de
 * sessão válido, o index.html nunca sai do servidor: o visitante recebe apenas
 * a tela de login. Isso é diferente de uma "senha em JavaScript" na página, que
 * não protege nada — ali o HTML já teria sido baixado e bastaria ver o código-fonte.
 *
 * Variáveis de ambiente (Vercel → Settings → Environment Variables):
 *   PAINEL_USUARIO  — usuário de acesso            (ex.: pergamum)
 *   PAINEL_SENHA    — senha de acesso              (use uma senha longa)
 *   SESSAO_SEGREDO  — texto aleatório longo, usado para assinar o cookie
 *
 * Sem essas variáveis configuradas o painel fica bloqueado por padrão.
 */

export const config = {
  // Protege tudo, exceto os arquivos internos da Vercel
  matcher: '/((?!_vercel|favicon.ico).*)',
};

const DURACAO_SESSAO = 60 * 60 * 12;   // 12 horas, em segundos
const NOME_COOKIE = 'painel_sessao';

/* ---------- utilidades de assinatura ---------- */

const enc = new TextEncoder();

function b64url(bytes) {
  let s = '';
  for (const b of new Uint8Array(bytes)) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

async function assinar(dados, segredo) {
  const chave = await crypto.subtle.importKey(
    'raw', enc.encode(segredo), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']
  );
  return b64url(await crypto.subtle.sign('HMAC', chave, enc.encode(dados)));
}

async function criarToken(usuario, segredo) {
  const payload = b64url(enc.encode(JSON.stringify({
    u: usuario,
    exp: Math.floor(Date.now() / 1000) + DURACAO_SESSAO,
  })));
  return `${payload}.${await assinar(payload, segredo)}`;
}

async function tokenValido(token, segredo) {
  if (!token || !token.includes('.')) return false;
  const [payload, assinatura] = token.split('.');
  if (assinatura !== await assinar(payload, segredo)) return false;
  try {
    const dados = JSON.parse(atob(payload.replace(/-/g, '+').replace(/_/g, '/')));
    return dados.exp > Math.floor(Date.now() / 1000);
  } catch {
    return false;
  }
}

/* Comparação de tamanho constante, para não vazar a senha pelo tempo de resposta */
async function iguais(a, b) {
  const segredo = 'comparacao';
  return (await assinar(String(a), segredo)) === (await assinar(String(b), segredo));
}

/* ---------- tela de login ---------- */

function paginaLogin(erro) {
  return `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="theme-color" content="#123821">
<meta name="robots" content="noindex, nofollow">
<title>Acesso restrito — Pergamum Contabilidade</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Lora:wght@600&family=Poppins:wght@400;500;600&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box}
body{
  margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;
  font-family:'Poppins',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;
  background:linear-gradient(160deg,#123821 0%,#0E2B19 100%);
  color:#15211A;-webkit-font-smoothing:antialiased;
}
.caixa{
  width:min(400px,100%);background:#fff;border-radius:18px;padding:32px 28px;
  box-shadow:0 18px 50px rgba(10,26,16,.35);
}
.marca{text-align:center;margin-bottom:26px}
.marca img{width:180px;height:auto;display:inline-block}
h1{
  font-family:'Lora',Georgia,serif;font-size:1.32rem;font-weight:600;
  margin:0 0 4px;letter-spacing:-.01em;text-align:center;
}
.sub{font-size:.82rem;color:#6B7C71;text-align:center;margin:0 0 24px}
label{
  display:block;font-size:.68rem;letter-spacing:.1em;text-transform:uppercase;
  color:#6B7C71;font-weight:500;margin-bottom:5px;
}
input{
  width:100%;min-height:48px;border:1px solid #C6D2C6;border-radius:10px;
  padding:0 14px;font-size:.95rem;font-family:inherit;color:#15211A;background:#F7F9F6;
  margin-bottom:16px;
}
input:focus{outline:none;border-color:#25623C;background:#fff;box-shadow:0 0 0 3px rgba(37,98,60,.15)}
button{
  width:100%;min-height:48px;border:none;border-radius:10px;cursor:pointer;
  background:#1A4A2E;color:#fff;font-family:inherit;font-size:.95rem;font-weight:500;
  transition:background 200ms ease;
}
button:hover{background:#25623C}
.erro{
  background:#F8E7E4;color:#A63A2C;border:1px solid rgba(166,58,44,.2);
  border-radius:10px;padding:10px 14px;font-size:.82rem;margin-bottom:18px;
}
.rodape{
  margin-top:22px;padding-top:16px;border-top:1px solid #DFE6DF;
  font-size:.7rem;color:#6B7C71;text-align:center;line-height:1.5;
}
</style>
</head>
<body>
  <main class="caixa">
    <div class="marca">
      <img src="data:image/png;base64," alt="Pergamum Contabilidade" style="width:180px;height:auto">
    </div>
    <h1>Acesso restrito</h1>
    <p class="sub">Painel de custo de folha</p>
    ${erro ? `<div class="erro">${erro}</div>` : ''}
    <form method="POST" action="/login">
      <label for="usuario">Usuário</label>
      <input id="usuario" name="usuario" type="text" autocomplete="username" autocapitalize="none" required autofocus>
      <label for="senha">Senha</label>
      <input id="senha" name="senha" type="password" autocomplete="current-password" required>
      <button type="submit">Entrar</button>
    </form>
    <p class="rodape">Este painel contém dados de folha de pagamento.<br>Não compartilhe suas credenciais.</p>
  </main>
</body>
</html>`;
}

function respostaLogin(erro, status = 200) {
  return new Response(paginaLogin(erro), {
    status,
    headers: {
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'no-store, must-revalidate',
      'x-robots-tag': 'noindex, nofollow',
    },
  });
}

/* ---------- middleware ---------- */

export default async function middleware(request) {
  const url = new URL(request.url);
  const usuarioOk = process.env.PAINEL_USUARIO;
  const senhaOk = process.env.PAINEL_SENHA;
  const segredo = process.env.SESSAO_SEGREDO;

  // Sem credenciais configuradas, o painel permanece fechado
  if (!usuarioOk || !senhaOk || !segredo) {
    return respostaLogin(
      'Acesso não configurado. Defina PAINEL_USUARIO, PAINEL_SENHA e SESSAO_SEGREDO nas variáveis de ambiente do projeto.',
      503
    );
  }

  // Sair
  if (url.pathname === '/sair') {
    const r = new Response(null, { status: 302, headers: { location: '/' } });
    r.headers.append('set-cookie', `${NOME_COOKIE}=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax`);
    return r;
  }

  // Envio do formulário
  if (url.pathname === '/login' && request.method === 'POST') {
    const form = await request.formData();
    const u = form.get('usuario') || '';
    const p = form.get('senha') || '';

    if (await iguais(u, usuarioOk) && await iguais(p, senhaOk)) {
      const token = await criarToken(String(u), segredo);
      const r = new Response(null, { status: 302, headers: { location: '/' } });
      r.headers.append(
        'set-cookie',
        `${NOME_COOKIE}=${token}; Path=/; Max-Age=${DURACAO_SESSAO}; HttpOnly; Secure; SameSite=Lax`
      );
      return r;
    }
    return respostaLogin('Usuário ou senha incorretos.', 401);
  }

  // Sessão válida? Só então o arquivo é entregue.
  const cookie = request.headers.get('cookie') || '';
  const token = cookie.split(';').map(c => c.trim()).find(c => c.startsWith(`${NOME_COOKIE}=`));
  if (token && await tokenValido(token.slice(NOME_COOKIE.length + 1), segredo)) {
    return; // segue para o arquivo estático
  }

  return respostaLogin(null, 401);
}
